/// `NPCID.Sets.NPCBestiaryDrawOffset.TryGetValue` (`UnlockableNPCEntryIcon.cs:52`).
pub fn get(net_id: i32) -> Option<&'static BestiaryDrawModifiers> {
    DRAW_OFFSETS
        .binary_search_by_key(&net_id, |(id, _)| *id)
        .ok()
        .map(|i| &DRAW_OFFSETS[i].1)
}
